package com.habitpro.controller;import com.habitpro.model.User;import com.habitpro.repository.UserRepository;import com.habitpro.security.JwtService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}public record Credentials(@NotBlank String username,@NotBlank @Size(min=6) String password,boolean remember){}public record AuthResponse(String token,String username){}public record Message(String message){}@PostMapping("/signup")public ResponseEntity<?> signup(@Valid @RequestBody Credentials c){String name=c.username().trim();if(users.findByUsername(name).isPresent())return ResponseEntity.badRequest().body(new Message("Username already exists"));User u=new User();u.setUsername(name);u.setPassword(encoder.encode(c.password()));users.save(u);return ResponseEntity.ok(new Message("Account created"));}@PostMapping("/login")public ResponseEntity<?> login(@RequestBody Credentials c){var u=users.findByUsername(c.username().trim());if(u.isEmpty()||!encoder.matches(c.password(),u.get().getPassword()))return ResponseEntity.status(401).body(new Message("Invalid username or password"));return ResponseEntity.ok(new AuthResponse(jwt.generate(u.get().getId(),u.get().getUsername()),u.get().getUsername()));}}